class CheckoutViewModel(private val repo: OrderRepo) : ViewModel() {

    // buffer = replay(0) + extraBufferCapacity(1) = 1
    // DROP_OLDEST => emit() never suspends and tryEmit() never returns false
    private val _events = MutableSharedFlow<UiEvent>(
        replay = 0,
        extraBufferCapacity = 1,
        onBufferOverflow = BufferOverflow.DROP_OLDEST,
    )
    val events: SharedFlow<UiEvent> = _events.asSharedFlow()

    fun onPayClicked() {
        viewModelScope.launch {
            when (val result = repo.pay()) {
                is PayResult.Ok ->
                    _events.emit(UiEvent.Navigate(result.orderId))   // returns immediately
                is PayResult.Failed ->
                    _events.emit(UiEvent.Snackbar(result.message))
            }
        }
    }
}

// replay = 0 also means: emitted while nobody is subscribed => the event is gone.
// The UI must already be inside repeatOnLifecycle before you emit.

// One consumer, nothing may be dropped: a Channel, not a SharedFlow.
private val _nav = Channel<NavCommand>(Channel.BUFFERED)  // 64 slots, producer suspends when full
val nav: Flow<NavCommand> = _nav.receiveAsFlow()          // each element goes to exactly ONE collector

// Start and stop the upstream with the audience -- this is what WhileSubscribed does internally.
init {
    viewModelScope.launch {
        _events.subscriptionCount
            .map { count -> count > 0 }
            .distinctUntilChanged()
            .collectLatest { hasListeners ->
                if (hasListeners) socket.connect() else socket.disconnect()
            }
    }
}

@OptIn(ExperimentalCoroutinesApi::class)
class SearchViewModel(
    private val repo: SearchRepo,
    savedState: SavedStateHandle,
) : ViewModel() {

    private val query: StateFlow<String> = savedState.getStateFlow("query", "")

    val state: StateFlow<UiState> = query
        .debounce(300)
        .flatMapLatest { q -> repo.observe(q) }            // cold: Room + network per query
        .map<List<Item>, UiState> { UiState.Content(it) }
        .catch { e -> emit(UiState.Error(e)) }
        .stateIn(
            scope = viewModelScope,                        // cancelled in onCleared()
            started = SharingStarted.WhileSubscribed(
                stopTimeoutMillis = 5_000,                 // spans the Activity recreation gap
                replayExpirationMillis = Long.MAX_VALUE,   // default: keep the value across a STOP
            ),
            initialValue = UiState.Loading,                // what the very first frame renders
        )
}

// Non-suspending: returns a StateFlow right now, initial value already readable.
val hot: StateFlow<Int> = upstream.stateIn(scope, SharingStarted.Eagerly, 0)

// SUSPENDING: waits for the upstream's first emission. On a flow that never emits,
// this never returns -- inside init { } that looks like a permanently dead screen.
suspend fun risky(): StateFlow<Int> = upstream.stateIn(scope)

// SharingStarted is an interface, so 'while subscribed OR while a sync is running' is trivial:
class WhileSubscribedOrSyncing(
    private val syncing: StateFlow<Boolean>,
) : SharingStarted {
    override fun command(subscriptionCount: StateFlow<Int>): Flow<SharingCommand> =
        combine(subscriptionCount, syncing) { count, busy -> count > 0 || busy }
            .distinctUntilChanged()
            .map { active -> if (active) SharingCommand.START else SharingCommand.STOP }
}

class FeedFragment : Fragment(R.layout.fragment_feed) {

    private val vm: FeedViewModel by viewModels()
    private var binding: FragmentFeedBinding? = null

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        binding = FragmentFeedBinding.bind(view)

        // viewLifecycleOwner, not `this`: on the back stack the Fragment survives,
        // the view does not. Using lifecycleScope here outlives onDestroyView().
        viewLifecycleOwner.lifecycleScope.launch {
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                vm.state.collect { state -> binding?.render(state) }
            }
        }
    }

    override fun onDestroyView() {
        binding = null   // safe precisely because the collector above is view-scoped
        super.onDestroyView()
    }
}

// What viewModelScope is, spelled out:
// CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)
// cancelled by ViewModel.clear(), which then calls onCleared().

class UploadViewModel(
    private val repo: DraftRepo,
    private val appScope: CoroutineScope,   // injected, Application lifetime
) : ViewModel() {

    private val _state = MutableStateFlow<SaveState>(SaveState.Idle)
    val state: StateFlow<SaveState> = _state.asStateFlow()

    fun save(draft: Draft) {
        viewModelScope.launch { _state.value = SaveState.Saving }  // dies with the screen
        appScope.launch { repo.upload(draft) }                     // must outlive the screen
        // GlobalScope.launch { } -- no parent, no cancellation, untestable. Never.
    }
}

// DEPRECATED: the consumer freezes, the producer does not.
viewLifecycleOwner.lifecycleScope.launchWhenStarted {
    locationManager.locations().collect { render(it) }   // GPS stays on while backgrounded
}

// CORRECT: one launch, one repeatOnLifecycle, N collectors nested inside it.
viewLifecycleOwner.lifecycleScope.launch {
    viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
        launch { vm.state.collect { state -> render(state) } }
        launch { vm.events.collect { event -> show(event) } }
        // Nothing written after repeatOnLifecycle runs until the lifecycle is DESTROYED.
    }
}

fun LocationManager.locations(): Flow<Location> = callbackFlow {
    val listener = LocationListener { location -> trySend(location) }
    requestLocationUpdates(LocationManager.GPS_PROVIDER, 1_000L, 0f, listener)

    // Runs only when the collecting coroutine is CANCELLED.
    // launchWhenStarted never gets here at STOP; repeatOnLifecycle gets here every time.
    awaitClose { removeUpdates(listener) }
}

// If restarting the cold upstream on every foreground is too expensive,
// make it hot once and let repeatOnLifecycle only add/remove the subscriber:
val locations: StateFlow<Location?> = locationManager.locations()
    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), null)

@Composable
fun FeedRoute(vm: FeedViewModel = viewModel()) {
    // repeatOnLifecycle(STARTED) underneath: unsubscribes at onStop, resubscribes at onStart.
    val state by vm.state.collectAsStateWithLifecycle()
    FeedScreen(state = state, onRefresh = vm::refresh)
}

@Composable
fun CameraRoute(vm: CameraViewModel = viewModel()) {
    // RESUMED: also drop the subscription when a dialog, or the other multi-window
    // pane, takes focus -- STARTED alone would keep the frames flowing.
    val frame by vm.frames.collectAsStateWithLifecycle(
        initialValue = Frame.Empty,
        minActiveState = Lifecycle.State.RESUMED,
    )
    CameraPreview(frame)
}

@Composable
fun BadSearch(vm: SearchViewModel, query: String) {
    // A NEW Flow instance on every recomposition -> the collection key changes ->
    // the collector is cancelled and restarted, and the cold upstream refetches.
    val items by vm.allItems
        .map { list -> list.filter { it.name.contains(query, ignoreCase = true) } }
        .collectAsStateWithLifecycle(initialValue = emptyList())

    ItemList(items)
}

@Composable
fun GoodSearch(vm: SearchViewModel) {
    // Filtering lives in the ViewModel; the composable collects one stable StateFlow
    // that already carries a real Loading state.
    val state by vm.state.collectAsStateWithLifecycle()

    when (state) {
        is UiState.Loading -> Spinner()
        is UiState.Content -> ItemList((state as UiState.Content).items)
        is UiState.Error -> ErrorPane(onRetry = vm::retry)
    }
}

@OptIn(ExperimentalCoroutinesApi::class)
@HiltViewModel
class SearchViewModel @Inject constructor(
    private val repo: SearchRepo,
    private val handle: SavedStateHandle,   // also carries the navigation arguments
) : ViewModel() {

    // SURVIVES process death: a short String written into the saved-state bundle.
    val query: StateFlow<String> = handle.getStateFlow(KEY_QUERY, "")

    fun onQueryChanged(text: String) {
        handle[KEY_QUERY] = text            // writing the key re-emits on the StateFlow
    }

    // Does NOT survive process death -- and does not need to. It is re-derived from
    // the restored query plus Room, which is on disk and therefore already durable.
    val results: StateFlow<UiState> = query
        .flatMapLatest { q -> repo.observe(q) }
        .map<List<Item>, UiState> { UiState.Content(it) }
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), UiState.Loading)

    private companion object { const val KEY_QUERY = "query" }
}

// Do not do this. The bundle rides a Binder transaction shared by the entire task,
// so this fails as TransactionTooLargeException on someone else's deep back stack.
handle["results"] = ArrayList(uiState.items)      // 3 000 parcelables

// Compose equivalent of the same registry, same budget:
var draft by rememberSaveable { mutableStateOf("") }   // fine: one short String

