@Test
fun hangs() = runTest {
    val vm = FeedViewModel(FakeRepo())
    val seen = mutableListOf<UiState>()

    launch { vm.state.toList(seen) }   // StateFlow never completes => 60s timeout, test fails

    vm.refresh()
    assertEquals(UiState.Content(items), seen.last())
}

@Test
fun passes() = runTest {
    val vm = FeedViewModel(FakeRepo())
    val seen = mutableListOf<UiState>()

    // backgroundScope is cancelled once the test body returns, so it cannot hold the test open.
    // Unconfined + the TEST's scheduler: emissions recorded as they happen, one virtual clock.
    backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
        vm.state.toList(seen)
    }

    vm.refresh()
    advanceUntilIdle()   // Main is a StandardTestDispatcher: nothing had run before this line
    assertEquals(UiState.Content(items), seen.last())
}

@Test
fun `upstream stops five seconds after the last subscriber leaves`() = runTest {
    val repo = CountingRepo()          // increments on collect, decrements in onCompletion
    val vm = FeedViewModel(repo)

    val subscriber = backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
        vm.state.collect { }
    }
    advanceUntilIdle()
    assertEquals(1, repo.activeCollections)

    subscriber.cancel()
    advanceTimeBy(4_999)
    assertEquals(1, repo.activeCollections)   // still inside the grace window

    advanceTimeBy(2)                          // 1.7+: advanceTimeBy does not run the task
    assertEquals(0, repo.activeCollections)   // scheduled at exactly currentTime + n
}
